<?php
session_start();require __DIR__.'/portal_lib.php';if(!ep_admin()){header('Location: admin.php');exit;}
$clients=ep_read('clientes');$quotes=ep_read('orcamentos');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ep_check();$action=$_POST['action']??'';
if($action==='client'){$user=trim((string)($_POST['user']??''));$pass=(string)($_POST['password']??'');$duplicate=false;foreach($clients as $c)if(strcasecmp($c['user'],$user)===0)$duplicate=true;if(!$user||strlen($pass)<8||$duplicate)$error='Informe usuário único e senha com no mínimo 8 caracteres.';else{$clients[]=['id'=>'cust_'.bin2hex(random_bytes(8)),'user'=>$user,'password'=>password_hash($pass,PASSWORD_DEFAULT),'name'=>trim((string)($_POST['name']??'')),'document'=>trim((string)($_POST['document']??'')),'phone'=>trim((string)($_POST['phone']??'')),'email'=>trim((string)($_POST['email']??'')),'active'=>true];ep_write('clientes',$clients);header('Location: portal_admin.php');exit;}}
if($action==='toggle'){foreach($clients as &$c)if(($c['id']??'')===($_POST['id']??''))$c['active']=empty($c['active']);unset($c);ep_write('clientes',$clients);header('Location: portal_admin.php');exit;}
if($action==='release'){$id=(string)($_POST['id']??'');foreach($quotes as &$q){if(($q['id']??'')!==$id||empty($q['client_id'])||!in_array($q['status']??'',['aguardando_analise','proposta_enviada'],true))continue;foreach($q['items'] as $k=>&$item)$item['discount']=max(0,min(100,(float)($_POST['item_discount'][$k]??0)));unset($item);$q['discount']=max(0,min(100,(float)($_POST['discount']??0)));$q['status']='proposta_enviada';$q['updated_at']=date('c');$q['history'][]=['at'=>date('c'),'user'=>$_SESSION['admin_user'],'event'=>'released'];break;}unset($q);ep_write('orcamentos',$quotes);header('Location: portal_admin.php');exit;}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administração do Portal ELEDS</title><?php ep_style();?></head><body><header><strong>ELEDS — Clientes e Aprovações</strong> <a href="admin.php">Voltar ao painel</a></header><main><?php if($error):?><p class="error"><?=ep_h($error)?></p><?php endif;?><section class="panel"><h2>Cadastrar cliente</h2><form method="post"><input type="hidden" name="csrf" value="<?=ep_csrf()?>"><input type="hidden" name="action" value="client"><label>Nome / empresa<br><input name="name" required></label><label>Usuário<br><input name="user" required></label><label>Senha inicial<br><input type="password" name="password" minlength="8" required></label><label>Documento<br><input name="document"></label><label>Telefone<br><input name="phone"></label><label>E-mail<br><input type="email" name="email"></label><button>Cadastrar cliente</button></form><h3>Clientes cadastrados</h3><table><tr><th>Cliente</th><th>Usuário</th><th>Status</th><th>Ação</th></tr><?php foreach($clients as $c):?><tr><td><?=ep_h($c['name'])?></td><td><?=ep_h($c['user'])?></td><td><?=!empty($c['active'])?'Ativo':'Bloqueado'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=ep_csrf()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=ep_h($c['id'])?>"><button><?=!empty($c['active'])?'Bloquear':'Ativar'?></button></form></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Orçamentos dos clientes</h2><?php foreach(array_reverse($quotes) as $q):if(empty($q['client_id']))continue;?><div class="panel"><div class="row"><h3><?=ep_h($q['number']??'')?> — <?=ep_h($q['customer']['name']??$q['user']??'')?></h3><strong><?=($q['status']??'')==='proposta_enviada'?'Proposta enviada':'Aguardando análise'?></strong></div><form method="post"><input type="hidden" name="csrf" value="<?=ep_csrf()?>"><input type="hidden" name="action" value="release"><input type="hidden" name="id" value="<?=ep_h($q['id'])?>"><table><tr><th>Produto</th><th>Quantidade</th><th>Preço unitário</th><th>Desconto individual (%)</th></tr><?php foreach(($q['items']??[]) as $k=>$i):?><tr><td><?=ep_h($i['code']??'')?> — <?=ep_h($i['name']??'')?></td><td><?= (int)($i['qty']??0)?></td><td><?=ep_money($i['price']??0)?></td><td><input type="number" min="0" max="100" step="0.01" name="item_discount[<?=$k?>]" value="<?=ep_h($i['discount']??0)?>" style="width:100px"></td></tr><?php endforeach;?></table><label>Desconto geral adicional (%) <input type="number" min="0" max="100" step="0.01" name="discount" value="<?=ep_h($q['discount']??0)?>" style="width:100px"></label><p>Total atual: <strong><?=ep_money(ep_total($q))?></strong></p><button onclick="return confirm('Liberar proposta final para o cliente?')">Salvar descontos e liberar proposta</button></form></div><?php endforeach;?></section></main></body></html>
